def answer(s):
 if s in ['Yes','No']:return {'Yes':'是','No':'否'}[s]
 m=re.match(r'Recorded scale value (.*?) on the dataset',s)
 return '原始量表值'+m[1]+'（0–10，端点含义未给出）' if m else s
def describe(items,full=False):
 v=items if full else items[:1]
 return '；'.join(LABELS.get(x['evidence_id'],x['question_en'])+'：'+answer(x['answer_en']) for x in v)
